package com.reviewflow.integration;
import com.reviewflow.domain.Business; import com.fasterxml.jackson.databind.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.http.*; import org.springframework.stereotype.Service; import org.springframework.web.client.RestClient;
@Service @ConditionalOnProperty(name="google.api-key") public class GooglePlacesReviewProvider implements GoogleReviewProvider { private final String key; private final RestClient http=RestClient.create(); private final ObjectMapper json=new ObjectMapper(); public GooglePlacesReviewProvider(@Value("${google.api-key}")String k){key=k;} public ReviewMetrics getBusinessMetrics(Business b){try{String id=b.googlePlaceId;if(id==null||id.isBlank()){String body="{\"textQuery\":\""+b.name.replace("\"","\\\"")+"\"}";String found=http.post().uri("https://places.googleapis.com/v1/places:searchText").header("X-Goog-Api-Key",key).header("X-Goog-FieldMask","places.id,places.displayName,places.rating,places.userRatingCount").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(String.class);JsonNode p=json.readTree(found).path("places").path(0);if(p.isMissingNode())throw new IllegalStateException("No matching Google place was found.");return new ReviewMetrics(p.path("rating").asDouble(),p.path("userRatingCount").asInt(),p.path("id").asText());}String details=http.get().uri("https://places.googleapis.com/v1/"+id).header("X-Goog-Api-Key",key).header("X-Goog-FieldMask","id,rating,userRatingCount").retrieve().body(String.class);JsonNode p=json.readTree(details);return new ReviewMetrics(p.path("rating").asDouble(),p.path("userRatingCount").asInt(),id);}catch(Exception e){throw new IllegalStateException("Google Places sync failed: "+e.getMessage(),e);}} }
